          'maxHearts', 'speed', 'water', 'shields', 'magnet', 'trade', 'pop', 'beds',
          'storage', 'durability', 'priceBonus', 'traffic', 'unlock', 'checkpoint',
          'waterRate', 'waterEvery', 'foodRate', 'foodEvery', 'tradeRatio',
