        if (!isObject(n.recruitCondition)) problems.push('npcs.' + n.id + '.recruitCondition: 缺失或不是对象');
        if (!isStr(n.specialty)) warnings.push('npcs.' + n.id + '.specialty: 缺失（后台按此展示特长，游戏暂不消费）');
