  for (var f = 0; f < FLY_COUNT; f++) flyBase.push((rand() - 0.5) * N * 0.9, 0.8 + rand() * 0.7, (rand() - 0.5) * N * 0.9, rand() * 10);
  flyGeo.setAttribute('position', new THREE.Float32BufferAttribute(new Float32Array(FLY_COUNT * 3), 3));
