    B.add(0.46, 2.66, -2.95, 0.92, 0.46, 0.1, '#ff8a4c');      // flag
    B.add(0.46, 2.66, -2.95, 0.92, 0.1, 0.11, '#e2574c');
    B.add(2.25, 1.32, 2.42, 0.1, 1.2, 0.1, '#6b4a2c');         // lantern post
