    pickups.push({ x: p.x, z: p.z, phase: Math.random() * 6, drift: Math.random() * 6, node: node, glow: glow, special: type, value: 0, glowColor: type === 'ring' ? '#ff9fb0' : '#ffd166', name: type === 'ring' ? '救生圈' : '宝箱' });
